def norm(value):
	key = str(value or "").strip().lower()
	if key in ["you", "me", "personal", "people", "for you"]:
		return "personal"
	if key in ["business", "company", "companies", "for your business"]:
		return "business"
	return "both"


def tag_of(aud):
	if aud == "personal":
		return "For you"
	if aud == "business":
		return "For your business"
	return ""


def read_rows(raw):
	if isinstance(raw, str):
		try:
			raw = json.loads(raw)
		except Exception:
			raw = [line for line in raw.split("\n") if line.strip()]
	if not isinstance(raw, list):
		return []
	return [str(line) for line in raw if str(line).strip()]


def split_row(line, size):
	parts = [part.strip() for part in str(line).split("|")]
	while len(parts) < size:
		parts.append("")
	return parts

rows = []
try:
	for line in read_rows(props.get("days")):
		parts = split_row(line, 4)
		if not parts[1]:
			continue
		shut = parts[2].strip().lower() in ["closed", "shut", ""]
		rows.append({"num": parts[0], "day": parts[1], "hours": parts[2] or "Closed", "note": parts[3], "shut": "true" if shut else "false"})
except Exception:
	rows = []
component.rows = rows
